contract InvMutTest is Test {
    C c;
    address constant OWNER = address(this);

    function setUp() public {
        c = new C(OWNER);
    }

    function testFuzz_property(uint256 amount, address recipient) public {
        // restrict to economic bounds
        amount = bound(amount, 1, 1_000_000 ether);
        vm.assume(recipient != address(0));
        vm.assume(recipient != OWNER); // the case where recipient == owner is true by design; we test the difference when they differ

        // fund the contract with a deposit
        vm.deal(address(c), amount);

        // record owner balance before
        uint256 ownerBalanceBefore = OWNER.balance;

        // owner calls withdrawAll(recipient)
        vm.prank(OWNER);
        (bool success, ) = address(c).call(abi.encodeWithSignature("withdrawAll(address)", recipient));
        require(success, "withdrawAll reverted");

        // After a successful withdrawAll by the owner, the contract balance must be zero.
        // This holds in the reference because funds are sent to recipient (an EOA).
        // In the buggy version, funds are sent to msg.sender (owner), so contract balance remains amount > 0.
        assertTrue(address(c).balance == 0);
    }
}

